import time
import sys
from functools import partial
from taf.internal.managed.ssh.authenticatable_runner import AuthenticatableShell
from taf.internal.managed.ssh.managed_ssh_connection import ManagedSshConnection
from taf.internal.protocol.tl1.exception import ReceiveOutputTimout


class Session(object):
    def send_message(self, msg, **kwargs):
        raise NotImplementedError

    def receive_message(self, timeout=5, **kwargs):
        raise NotImplementedError


class TL1SSHShellSession(AuthenticatableShell, Session):
    def __init__(self,
                 host,
                 port,
                 username,
                 password,
                 command_postfix="\r",
                 prompt='agent>',  # agent> is prompt of calient tl1 shell, please replace according to the device
                 encoding='utf-8',
                 **kwargs):
        super(TL1SSHShellSession, self).__init__(None, command_postfix=command_postfix, **kwargs)
        self._managed_ssh_connection = ManagedSshConnection(
            host=host, port=port, user=username, password=password)
        self.add_prerequisite(self._managed_ssh_connection)
        self.prompt = prompt
        if sys.version_info.major == 3:
            self.read = partial(self.read_output_py3, encoding=encoding)
        else:
            self.read = self.read_output_py2

    def _setup(self):
        self._ssh_connection = self._managed_ssh_connection.ssh_connection
        super(TL1SSHShellSession, self)._setup()
        self.read_until(expectstr=self.prompt, timeout=10)  # clear the output generated for ssh login

    def send_message(self, msg, **kwargs):
        return self.send_command(msg)

    def receive_message(self, message_terminator=';', timeout=10, **kwargs):
        """
        the reason why not use prompt to decide when to end the read is because of the canc-user exitsess=y
        then there will no prompt to be as the end flag
        """
        text_with_command_sent, time_escape = self.read_until(message_terminator, timeout)
        message_count = text_with_command_sent.count(message_terminator)
        command_end_index = text_with_command_sent.find(message_terminator)
        if message_count > 1:  # not only the command but also the response output
            return text_with_command_sent[command_end_index + 1:]
        if message_count == 1:  # only command, need read response output further
            prior_text_without_command = text_with_command_sent[command_end_index + 1:]
            output, _ = self.read_until(message_terminator, timeout - time_escape)
            return prior_text_without_command + output

    def read_until(self, expectstr, timeout):
        if not expectstr:
            return "", 0

        output = ""
        start = time.time()
        end = start + timeout
        while time.time() < end:
            output += self.read()
            if expectstr in output:
                return output, time.time() - start
            time.sleep(1)

        raise ReceiveOutputTimout("'{}' not contain '{}'".format(output, expectstr))

    def read_output_py2(self):
        output = ""
        if self._session.recv_ready():
            output += self._session.recv(self._READ_BYTE_SIZE)

        if self._session.recv_stderr_ready():
            output += self._session.recv_stderr(self._READ_BYTE_SIZE)
        return output

    def read_output_py3(self, encoding='utf-8'):
        output = ""
        if self._session.recv_ready():
            output += self._session.recv(self._READ_BYTE_SIZE).decode(encoding)

        if self._session.recv_stderr_ready():
            output += self._session.recv_stderr(self._READ_BYTE_SIZE).decode(encoding)
        return output
